(()=>{const v=document.getElementById('calm-film'),b=document.getElementById('film-toggle');if(!v||!b)return;const reduce=matchMedia('(prefers-reduced-motion: reduce)');let wanted=!reduce.matches&&!navigator.connection?.saveData,visible=true;const label=()=>{b.textContent=v.paused?'Play motion':'Pause motion';b.setAttribute('aria-label',v.paused?'Play background motion':'Pause background motion')};const sync=()=>{if(wanted&&visible&&!document.hidden){if(!v.src)v.src=v.dataset.src;v.play().catch(()=>{wanted=false;label()})}else v.pause()};b.hidden=false;b.addEventListener('click',()=>{wanted=!wanted;sync()});v.addEventListener('play',label);v.addEventListener('pause',label);v.addEventListener('error',()=>{b.hidden=true;v.hidden=true});reduce.addEventListener('change',()=>{wanted=!reduce.matches;sync()});document.addEventListener('visibilitychange',sync);new IntersectionObserver(e=>{visible=e[0].isIntersecting;sync()},{threshold:.05}).observe(v);label();sync()})();